/**
 * Drift guard for the rv-odt.json split (startup-bundle budget): `schema/v1/rv-odt.json` stays the
 * source of truth, `rv-odt.structure.json` (eager) and `rv-odt.descriptions.json` (lazy) are
 * generated by `scripts/gen-odt-split.mjs`. A hand edit of either generated file, or an edit of the
 * source without `npm run gen:odt-split`, fails here.
 */

import { describe, it, expect } from 'vitest';
import { readFileSync } from 'node:fs';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { renderOdtSplit, splitOdt, STRUCTURE_FILE, DESCRIPTIONS_FILE, SOURCE_FILE } from '../scripts/gen-odt-split.mjs';

describe('rv-odt split --check', () => {
  it('exits 0, so a source edit without the generator fails early (fix: npm run gen:odt-split)', () => {
    const script = fileURLToPath(new URL('../scripts/gen-odt-split.mjs', import.meta.url));
    const r = spawnSync(process.execPath, [script, '--check'], { encoding: 'utf8' });
    expect(r.status, 'schema/v1/rv-odt*.json is stale - run: npm run gen:odt-split: ' + r.stderr + r.stdout).toBe(0);
  });
});

describe('rv-odt split files', () => {
  it('match what the generator produces from rv-odt.json (run: npm run gen:odt-split)', () => {
    const out = renderOdtSplit();
    expect(readFileSync(STRUCTURE_FILE, 'utf8').replace(/\r\n/g, '\n')).toBe(out.structure);
    expect(readFileSync(DESCRIPTIONS_FILE, 'utf8').replace(/\r\n/g, '\n')).toBe(out.descriptions);
  });

  it('structure has no description strings, and nothing else is lost', () => {
    const source = JSON.parse(readFileSync(SOURCE_FILE, 'utf8'));
    const { structure, descriptions } = splitOdt(source);
    expect(JSON.stringify(structure)).not.toContain('"description":"');
    expect(Object.keys(descriptions).length).toBeGreaterThan(100);
    // Re-inserting every description at its path restores the source byte for byte.
    const restored = JSON.parse(JSON.stringify(structure));
    for (const [path, text] of Object.entries(descriptions)) {
      const keys = path === '' ? [] : path.split('/');
      let node = restored;
      for (const k of keys) node = node[k];
      node.description = text;
    }
    expect(restored).toEqual(source);
  });

  it('a property NAMED description is kept (it is an object, not the keyword)', () => {
    const { structure, descriptions } = splitOdt({
      $defs: { T: { description: 'type', properties: { description: { type: 'string', description: 'field' } } } },
    });
    expect(structure).toEqual({ $defs: { T: { properties: { description: { type: 'string' } } } } });
    expect(descriptions).toEqual({
      '$defs/T': 'type',
      '$defs/T/properties/description': 'field',
    });
  });
});
